        type: 'paragraph',
        text: 'O custo da sondagem SPT para uma residência unifamiliar normalmente representa menos de 1% do valor total da obra. Quando comparamos esse investimento com os custos de correção de problemas estruturais — que podem chegar a 30% do valor da obra ou até inviabilizar o imóvel — fica claro que a sondagem é um investimento e não um custo.'
